/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoPipe, TranslocoService } from '@jsverse/transloco';
import { map } from 'rxjs';

/** Área de la aplicación, desde `sections.features.items.<clave>` del i18n. */
export interface Feature {
  key: string;
  icon?: string;
  title: string;
  text: string;
}

let nextId = 0;

/**
 * Tarjetas con lo que ofrece la aplicación. El contenido sale del i18n (`sections.features`), así que cada
 * aplicación cuenta lo suyo sin tocar el componente; sin entradas no se pinta nada.
 */
@Component({
  selector: 'app-features-section',
  standalone: true,
  imports: [MatIconModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './features-section.component.html',
  styleUrl: './features-section.component.scss',
})
export class FeaturesSectionComponent {
  private readonly items = toSignal(
    inject(TranslocoService)
      .selectTranslateObject<Record<string, Omit<Feature, 'key'>>>('sections.features.items')
      // Sin traducción, Transloco devuelve la propia clave como texto
      .pipe(map((value) => (value && typeof value === 'object' ? value : {}))),
    { initialValue: {} },
  );

  readonly features = computed<Feature[]>(() =>
    Object.entries(this.items()).map(([key, feature]) => ({ key, ...feature })),
  );
  readonly titleId = `features-title-${nextId++}`;
}
